script:
const owner = context.repo.owner;
const repo = context.repo.repo;
const pullRequest = context.payload.pull_request;
const sha = pullRequest?.head?.sha;

if (!sha) {
  core.setFailed('PR head SHA unavailable; cannot publish authoritative guard result.');
  return;
}

async function readTrustedRegistry(parameters) {
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      return await github.rest.repos.getContent(parameters);
    } catch (error) {
      const status = error?.status || error?.response?.status;
      const headers = error?.response?.headers || {};
      const limited = status === 403 && String(headers['x-ratelimit-remaining']) === '0';
      const retryable = !status || status === 429 || limited || (status >= 500 && status < 600);
      if (!retryable || attempt === 3) throw error;
      await new Promise(resolve => setTimeout(resolve, attempt * 1000));
    }
  }
}
function routingLabelsFromRegistry(text) {
  // Parse only the canonical agents mapping, never execute registry contents.
  const labels = new Set(['agent:auto', 'agent:copilot', 'agents:auto-pilot', 'agents:keepalive']);
  const agents = new Map();
  let inAgents = false;
  let sections = 0;
  let key = null;
  let enabledSeen = false;
  const finishEntry = () => {
    if (key !== null && !enabledSeen) throw new Error('Agent enabled flag is missing');
  };
  for (const raw of String(text).split(/\r?\n/)) {
    const line = raw.replace(/\s+#.*$/, '').replace(/\s+$/, '');
    if (!line.trim() || line.trimStart().startsWith('#')) continue;
    if (line.includes('\t')) throw new Error('Agent registry tabs are unsupported');
    if (/^agents:\s*$/.test(line)) { finishEntry(); inAgents = true; sections++; key = null; continue; }
    if (/^\S/.test(line)) { finishEntry(); inAgents = false; key = null; continue; }
    if (!inAgents) continue;
    const entry = line.match(/^  ([a-z][a-z0-9_-]*):\s*$/);
    if (entry) {
      finishEntry();
      key = entry[1];
      if (agents.has(key)) throw new Error('Duplicate agent registry entry');
      agents.set(key, false);
      enabledSeen = false;
      continue;
    }
    if (/^  \S/.test(line) || !key) throw new Error('Malformed agent registry entry');
    if (/^    enabled:/.test(line)) {
      const value = line.match(/^    enabled:\s*(true|false)$/);
      if (!value || enabledSeen) throw new Error('Malformed agent enabled flag');
      enabledSeen = true;
      agents.set(key, value[1] === 'true');
    }
  }
  finishEntry();
  if (sections !== 1 || agents.size === 0) throw new Error('Agent registry mapping is incomplete');
  for (const [agent, enabled] of agents) if (enabled) labels.add(`agent:${agent}`);
  return labels;
}
const targetUrl =
  process.env.TARGET_URL ||
  `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function withApiRetry(
  fn,
  { label = 'operation', maxAttempts = 5, baseDelay = 1000 } = {},
) {
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await fn(github);
    } catch (error) {
      const status = error?.status || error?.response?.status;
      const headers = error?.response?.headers || {};
      const remainingRaw =
        headers['x-ratelimit-remaining'] ?? headers['X-RateLimit-Remaining'];
      const resetRaw = headers['x-ratelimit-reset'] ?? headers['X-RateLimit-Reset'];
      const remaining = Number(remainingRaw);
      const reset = Number(resetRaw);
      const isRateLimit =
        status === 403 && Number.isFinite(remaining) && remaining <= 0;
      const retryable =
        isRateLimit ||
        status === 429 ||
        !status ||
        (status >= 500 && status < 600);
      if (!retryable || attempt === maxAttempts) {
        core.error(`Failed ${label}: ${error.message}`);
        throw error;
      }
      let delay = baseDelay * attempt;
      const retryAfterRaw = headers['retry-after'] ?? headers['Retry-After'];
      const retryAfterSeconds = Number(retryAfterRaw);
      if (Number.isFinite(retryAfterSeconds) && retryAfterSeconds > 0) {
        delay = Math.max(delay, retryAfterSeconds * 1000);
      } else if (isRateLimit && Number.isFinite(reset)) {
        const nowSeconds = Math.floor(Date.now() / 1000);
        if (reset > nowSeconds) {
          const untilReset = (reset - nowSeconds) * 1000 + 500;
          delay = Math.max(delay, untilReset);
        }
      }
      delay = Math.max(delay, 1000);
      const humanDelay = delay >= 60000
        ? `${(delay / 60000).toFixed(2)}m`
        : `${Math.round(delay)}ms`;
      core.warning(
        `Retrying ${label} after ${humanDelay} ` +
          `(attempt ${attempt + 1}/${maxAttempts}).`
      );
      await sleep(delay);
    }
  }
  throw new Error(`Failed ${label} after ${maxAttempts} attempts.`);
}

async function assertCorrectiveWriteBinding() {
  const expectedAttempt = Number(process.env.GITHUB_RUN_ATTEMPT);
  if (!Number.isSafeInteger(pullRequest.number) || pullRequest.number <= 0 ||
      !Number.isSafeInteger(expectedAttempt) || expectedAttempt < 1 ||
      !pullRequest.base?.repo?.id || !pullRequest.base?.ref ||
      !/^[0-9a-f]{40}$/.test(pullRequest.base?.sha || '')) {
    throw new Error('Corrective guard publication binding is incomplete');
  }
  const readRun = async () => (await github.rest.actions.getWorkflowRun({
    owner, repo, run_id: context.runId,
  })).data;
  const validatePr = async () => {
    const current = (await github.rest.pulls.get({
      owner, repo, pull_number: pullRequest.number,
    })).data;
    if (current?.state !== 'open' || current.number !== pullRequest.number ||
        current.head?.sha !== sha || current.base?.sha !== pullRequest.base.sha ||
        current.base?.repo?.id !== pullRequest.base.repo.id ||
        current.base?.ref !== pullRequest.base.ref) {
      throw new Error('PR binding changed before corrective guard publication');
    }
  };
  const validateRun = run => {
    if (Number(run?.id) !== Number(context.runId) ||
        !/^\.github\/workflows\/agents-guard\.yml(?:@[^\s@]+)?$/.test(run?.path || '') ||
        run?.name !== 'Health 45 Agents Guard' ||
        run?.event !== context.eventName ||
        run?.head_sha !== (context.eventName === 'pull_request' ? sha : context.sha) ||
        Number(run?.run_attempt) !== expectedAttempt ||
        !Number.isSafeInteger(Number(run?.workflow_id)) || Number(run.workflow_id) <= 0 ||
        !Number.isSafeInteger(Number(run?.run_number)) || Number(run.run_number) <= 0 ||
        !/^\d{4}-\d{2}-\d{2}T/.test(run?.created_at || '')) {
      throw new Error('Run binding changed before corrective guard publication');
    }
  };
  await validatePr();
  const run = await readRun();
  validateRun(run);
  const workflow = (await github.rest.actions.getWorkflow({
    owner, repo, workflow_id: run.workflow_id,
  })).data;
  if (Number(workflow?.id) !== Number(run.workflow_id) ||
      workflow?.path !== '.github/workflows/agents-guard.yml' ||
      workflow?.name !== 'Health 45 Agents Guard') {
    throw new Error('Run is not the canonical Agents Guard workflow');
  }
  const runs = await github.paginate(github.rest.actions.listWorkflowRuns, {
    owner, repo, workflow_id: run.workflow_id, event: run.event,
    created: `>=${run.created_at}`, per_page: 100,
  });
  if (!Array.isArray(runs) || runs.filter(candidate =>
    Number(candidate.id) === Number(run.id) &&
    Number(candidate.run_attempt) === expectedAttempt
  ).length !== 1) throw new Error('Latest guard run inventory is incomplete');
  for (const candidate of runs) {
    const newer = Number(candidate.run_number) > Number(run.run_number) ||
      (Number(candidate.id) === Number(run.id) && Number(candidate.run_attempt) > expectedAttempt);
    if (!newer) continue;
    const associated = candidate.pull_requests;
    if (!Array.isArray(associated) ||
        associated.some(pr => !Number.isSafeInteger(Number(pr?.number)) || Number(pr.number) <= 0) ||
        associated.some(pr => Number(pr?.number) === pullRequest.number) ||
        (associated.length === 0 && candidate.head_sha === run.head_sha)) {
      throw new Error('Guard run was superseded or newer PR association is ambiguous');
    }
  }
  await validatePr();
  const finalRun = await readRun();
  validateRun(finalRun);
  if (finalRun.path !== run.path || finalRun.name !== run.name ||
      Number(finalRun.workflow_id) !== Number(run.workflow_id) ||
      Number(finalRun.run_number) !== Number(run.run_number) ||
      finalRun.created_at !== run.created_at) {
    throw new Error('Run identity changed before corrective guard publication');
  }
}

try {
  let routingLabels;
  try {
    const registryRef = pullRequest?.base?.sha;
    if (!/^[0-9a-f]{40}$/.test(registryRef || '')) throw new Error('Trusted registry base SHA is missing');
    const registry = (await readTrustedRegistry({
      owner, repo, path: '.github/agents/registry.yml', ref: registryRef,
    })).data;
    if (registry?.type !== 'file' || registry.encoding !== 'base64') throw new Error('Agent registry evidence is incomplete');
    routingLabels = routingLabelsFromRegistry(Buffer.from(registry.content, 'base64').toString('utf8'));
  } catch (error) {
    // Only a current PR/run attempt may invalidate earlier success.
    // Stale or incomplete bindings must not write a corrective verdict.
    await assertCorrectiveWriteBinding();
    await withApiRetry(client => client.rest.repos.createCommitStatus({
      owner, repo, sha, state: 'failure',
      context: 'Health 45 Agents Guard / guard',
      description: `[guard-pr:${pullRequest.number}] Trusted registry evidence unavailable; fresh evaluation required.`,
      target_url: targetUrl,
    }), {label: 'invalidate guard status without trusted registry evidence'});
    core.setFailed(`Trusted registry evidence unavailable: ${error.message}`);
    return;
  }
  const permissionLabel = 'agents:allow-change';
  const policyLabelNames = (labels) => {
    if (!Array.isArray(labels)) {
      throw new Error('PR label evidence is incomplete.');
    }
    const names = labels.map((label) => {
      if (typeof label?.name !== 'string') {
        throw new Error('PR label evidence is malformed.');
      }
      const raw = label.name;
      const routing = raw.trim().toLowerCase();
      if (routingLabels.has(routing)) return routing;
      return raw.toLowerCase() === permissionLabel ? permissionLabel : '';
    }).filter(Boolean);
    return [...new Set(names)].sort();
  };
  const snapshotLabels = policyLabelNames(pullRequest?.labels);

  const blocked = (process.env.BLOCKED || '').toLowerCase() === 'true';
  const summary = process.env.SUMMARY || '';
  const evaluated = process.env.ELIGIBLE === 'true'
    && process.env.EVALUATE_OUTCOME === 'success'
    && process.env.BLOCKED === 'false';
  const safelySkipped = process.env.ELIGIBLE === 'false';
  const passed = process.env.JOB_STATUS === 'success'
    && (safelySkipped || evaluated) && !blocked;
  let state = passed ? 'success' : 'failure';
  let description = summary || (!passed
    ? 'Health 45 Agents Guard blocked this pull request.'
    : 'Health 45 Agents Guard passed.');

  function setFailure(reason) {
    state = 'failure';
    description = reason;
  }

  async function policyFingerprint(labels) {
    const canonical = labels.join('\n');
    const digest = await crypto.subtle.digest(
      'SHA-256', new TextEncoder().encode(canonical),
    );
    return Array.from(new Uint8Array(digest))
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join('');
  }

  function finalizeDescription(fingerprint) {
    if (!Number.isSafeInteger(pullRequest.number) || pullRequest.number <= 0) {
      throw new Error('Current pull request number is missing or invalid.');
    }
    const prefix = `[guard-pr:${pullRequest.number}] `;
    const receipt = state === 'success'
      ? ` [guard-policy-sha256:${fingerprint}]`
      : '';
    const maximum = 140 - prefix.length - receipt.length;
    if (description.length > maximum) {
      description = `${description.slice(0, maximum - 3)}...`;
    }
    description = `${prefix}${description}${receipt}`;
  }

  const currentLabels = await withApiRetry(
    (client) => client.paginate(client.rest.issues.listLabelsOnIssue, {
      owner, repo, issue_number: pullRequest.number, per_page: 100,
    }),
    { label: 'read current PR labels before publishing guard status' },
  );
  if (!Array.isArray(currentLabels)) {
    throw new Error('Current PR label evidence is incomplete.');
  }
  const currentLabelNames = policyLabelNames(currentLabels);
  const currentPolicyFingerprint = await policyFingerprint(currentLabelNames);
  const labelsChanged =
    JSON.stringify(currentLabelNames) !== JSON.stringify(snapshotLabels);
  if (evaluated && state === 'success') {
    let evaluatedLabelNames;
    try {
      const evaluatedLabels = JSON.parse(process.env.EVALUATED_LABELS || '');
      evaluatedLabelNames = policyLabelNames(evaluatedLabels);
    } catch (error) {
      setFailure('Agents Guard evaluated label evidence is missing or malformed; fresh evaluation required.');
    }
    if (evaluatedLabelNames &&
        JSON.stringify(evaluatedLabelNames) !== JSON.stringify(currentLabelNames)) {
      setFailure('PR labels changed after guard evaluation; fresh evaluation required.');
    }
  }
  if (labelsChanged) {
    // Never let a stale eligible evaluation retain a green required
    // context after its routing labels have changed.
    setFailure('PR labels changed after guard evaluation; fresh evaluation required.');
  }
  if (!labelsChanged && process.env.ELIGIBLE === 'false') {
    const statuses = await withApiRetry(
      (client) => client.paginate(client.rest.repos.listCommitStatusesForRef, {
        owner, repo, ref: sha, per_page: 100,
      }),
      { label: 'read existing exact-head guard status' },
    );
    if (!Array.isArray(statuses)) {
      throw new Error('Incomplete exact-head status inventory.');
    }
    const existing = statuses.find(
      (status) => status.context === 'Health 45 Agents Guard / guard',
    );
    if (existing) {
      if (context.eventName === 'pull_request_target' && existing.state === 'success') {
        if (typeof existing.description === 'string'
            && existing.description.startsWith(`[guard-pr:${pullRequest.number}] `)
            && existing.description.endsWith(` [guard-policy-sha256:${currentPolicyFingerprint}]`)) {
          core.info('Ineligible PR event: preserving policy-bound exact-head success.');
          return;
        }
        // A changed, missing, or malformed policy receipt cannot
        // retain a green context. A fresh eligible run may recover it.
        setFailure('Health 45 Agents Guard policy changed; fresh evaluation required.');
      } else {
        core.info('Ineligible PR event: preserving existing exact-head guard verdict.');
        return;
      }
    } else if (context.eventName === 'pull_request_target') {
      core.info('Ineligible PR event: leaving absent exact-head guard verdict absent.');
      return;
    }
  }
  finalizeDescription(currentPolicyFingerprint);
  await withApiRetry(
    (client) => client.rest.repos.createCommitStatus({
      owner,
      repo,
      sha,
      state,
      context: 'Health 45 Agents Guard / guard',
      description,
      target_url: targetUrl,
    }),
    { label: 'update guard commit status' },
  );
  core.info(`Updated Health 45 Agents Guard commit status to ${state}.`);
} catch (error) {
  core.setFailed(
    `Failed to update Health 45 Agents Guard commit status: ${error.message}`
  );
}
